actions.script:
def modules = [
    '/Dashboard':null, '/Contacts':'contacts', '/sales':'sales', '/Purchase':'purchase',
    '/Crm':'crm', '/pos':'pos', '/pos/Terminal':'pos', '/kot':'kot', '/pricing':'pricing',
    '/Inventory':'inventory', '/manufacturing':'manufacturing', '/project':'project',
    '/Stores':null, '/barcode':'barcode', '/Accounting':'accounting', '/tax':'tax',
    '/payroll':'payroll', '/expenses':'expenses'
]
def org = ec.user.getPreference('ACTIVE_ORGANIZATION')
def prefKey = 'ZC_SIDEBAR_V1_' + ((org && org != '_NA_') ? org : 'NO_ORG')
preference = ec.user.getPreference(prefKey) ?: ''
def isAdmin = ec.user.isInGroup('ADMIN') || ec.user.isInGroup('ZENITH_ADMIN')
def groups = (ec.user.userGroupIdSet ?: []) as List
def zenithRoles = groups.findAll { it?.startsWith('ZENITH_') && it != 'ZENITH_ALL' }
def posOnly = !ec.user.isInGroup('ADMIN') && zenithRoles.size() == 1 && zenithRoles.contains('ZENITH_CASHIER')
def plan = null
boolean disabled = ec.artifactExecution.disableAuthz()
try {
    if (org && org != '_NA_' && !ec.user.isInGroup('ADMIN')) {
        def tenant = ec.entity.find('zenith.erp.saas.SaasTenant')
            .condition('organizationPartyId', org).condition('statusId', 'SaasTenantActive').list()
        if (tenant) {
            plan = ec.entity.find('zenith.erp.saas.SaasPlanModule')
                .condition('planId', tenant[0].planId).list()
                .collect { it.moduleId?.toLowerCase() } as Set
        }
    }
} finally { if (!disabled) ec.artifactExecution.enableAuthz() }
def navigation = ec.service.sync().name('zenith.base.SecurityServices.get#ModuleNavigation')
    .parameter('planModules',plan != null ? plan as List : null).disableAuthz().call()
if (navigation.roleScope?.restricted) {
    allowedIds = (navigation.roleSections ?: [])*.mount
    return
}
allowedIds = modules.findAll { id, mod ->
    if (posOnly) return id in ['/Dashboard','/pos','/pos/Terminal','/Inventory']
    if (mod == null) return true
    if (mod == 'kot') return navigation.moduleIds == null || navigation.moduleIds.contains('kot')
    if (plan != null && !plan.contains('all') && !plan.contains(mod)) return false
    if (plan != null && !plan.contains('all') && !isAdmin && groups && !navigation.moduleIds.contains(mod)) return false
    return true
}.keySet() as List

if (payload.toString().length() > 4096) { error = 'Sidebar settings are too large.'; return }
def parsed
try { parsed = new groovy.json.JsonSlurper().parseText(payload.toString()) }
catch (Exception e) { error = 'Invalid sidebar settings.'; return }
if (!(parsed instanceof Map) || parsed.version != 1 || !(parsed.order instanceof List)
        || !(parsed.hidden instanceof List)) {
    error = 'Invalid sidebar settings.'; return
}
def config = ec.service.sync().name('zenith.app.SidebarServices.get#SidebarConfiguration')
    .parameters([:]).call()
def allowed = (config.allowedIds ?: []) as Set
def order = parsed.order
def hidden = parsed.hidden
if (order.any { !(it instanceof String) || !allowed.contains(it) }
        || hidden.any { !(it instanceof String) || !allowed.contains(it) }
        || order.size() != (order as Set).size()
        || hidden.size() != (hidden as Set).size()) {
    error = 'Sidebar contains an unavailable or duplicate module.'; return
}
def clean = groovy.json.JsonOutput.toJson([version:1, order:order, hidden:hidden])
def org = ec.user.getPreference('ACTIVE_ORGANIZATION')
def key = 'ZC_SIDEBAR_V1_' + ((org && org != '_NA_') ? org : 'NO_ORG')
ec.user.setPreference(key, clean)
preference = clean

def root = ec.screen.getScreenDefinition('component://zenith-erp-app/screen/zenith/ZenithApp.xml')
if (module != '__dash' && !root.subscreensItemsSorted.any { it.name == module }) { error = 'Unknown navigation module.'; return }
def org = ec.user.getPreference('ACTIVE_ORGANIZATION')
def key = 'ZC_SUBNAV_V1_' + ((org && org != '_NA_') ? org : 'NO_ORG') + '_' + module
preference = ec.user.getPreference(key) ?: ''

def root = ec.screen.getScreenDefinition('component://zenith-erp-app/screen/zenith/ZenithApp.xml')
if (module != '__dash' && !root.subscreensItemsSorted.any { it.name == module }) { error = 'Unknown navigation module.'; return }
if (payload.toString().length() > 8192) { error = 'Navigation settings are too large.'; return }
def parsed
try { parsed = new groovy.json.JsonSlurper().parseText(payload.toString()) }
catch (Exception e) { error = 'Invalid navigation settings.'; return }
if (!(parsed instanceof Map) || parsed.version != 1 || !(parsed.order instanceof List)
        || !(parsed.hidden instanceof List) || parsed.order.size() > 80 || parsed.hidden.size() > 80) {
    error = 'Invalid navigation settings.'; return
}
def sectionModule = module == 'kot' ? '(kot|pos)' : module
def valid = { id -> id instanceof String && id.length() <= 100 &&
    (module == '__dash' ? id == '/' || id ==~ /\/[A-Za-z][A-Za-z0-9\/-]*/ :
        id ==~ ('/' + sectionModule + '/[A-Za-z][A-Za-z0-9-]*')) }
if (parsed.order.any { !valid(it) } || parsed.hidden.any { !valid(it) }
        || parsed.order.size() != (parsed.order as Set).size()
        || parsed.hidden.size() != (parsed.hidden as Set).size()) {
    error = 'Navigation contains an invalid or duplicate section.'; return
}
def clean = groovy.json.JsonOutput.toJson([version:1, order:parsed.order, hidden:parsed.hidden])
def org = ec.user.getPreference('ACTIVE_ORGANIZATION')
def key = 'ZC_SUBNAV_V1_' + ((org && org != '_NA_') ? org : 'NO_ORG') + '_' + module
ec.user.setPreference(key, clean)
preference = clean
